{ pkgs, ... }:
{
  xdg.configFile."herdr/config.toml".text = ''
    onboarding = false

    [theme]
    name = "catppuccin"

    [terminal]
    default_shell = "${pkgs.nushell}/bin/nu"
  '';
}

keybinds clear-defaults=true {
    locked {
        bind "ctrl g" {
            SwitchToMode "Normal"
        }
    }
    resize {
        bind "r" {
            SwitchToMode "Normal"
        }
        bind "h" "Left" {
            Resize "Increase Left"
        }
        bind "j" "Down" {
            Resize "Increase Down"
        }
        bind "k" "Up" {
            Resize "Increase Up"
        }
        bind "l" "Right" {
            Resize "Increase Right"
        }
        bind "H" {
            Resize "Decrease Left"
        }
        bind "J" {
            Resize "Decrease Down"
        }
        bind "K" {
            Resize "Decrease Up"
        }
        bind "L" {
            Resize "Decrease Right"
        }
        bind "=" "+" {
            Resize "Increase"
        }
        bind "-" {
            Resize "Decrease"
        }
    }
    pane {
        bind "p" {
            SwitchToMode "Normal"
        }
        bind "h" "Left" {
            MoveFocus "Left"
        }
        bind "l" "Right" {
            MoveFocus "Right"
        }
        bind "j" "Down" {
            MoveFocus "Down"
        }
        bind "k" "Up" {
            MoveFocus "Up"
        }
        bind "Tab" {
            SwitchFocus
        }
        bind "n" {
            NewPane
            SwitchToMode "Locked"
        }
        bind "d" {
            NewPane "Down"
            SwitchToMode "Locked"
        }
        bind "r" {
            NewPane "Right"
            SwitchToMode "Locked"
        }
        bind "s" {
            NewPane "stacked"
            SwitchToMode "Locked"
        }
        bind "x" {
            CloseFocus
            SwitchToMode "Locked"
        }
        bind "f" {
            ToggleFocusFullscreen
            SwitchToMode "Locked"
        }
        bind "z" {
            TogglePaneFrames
            SwitchToMode "Locked"
        }
        bind "w" {
            ToggleFloatingPanes
            SwitchToMode "Locked"
        }
        bind "e" {
            TogglePaneEmbedOrFloating
            SwitchToMode "Locked"
        }
        bind "c" {
            SwitchToMode "RenamePane"
            PaneNameInput 0
        }
        bind "i" {
            TogglePanePinned
            SwitchToMode "Locked"
        }
    }
    move {
        bind "m" {
            SwitchToMode "Normal"
        }
        bind "n" "Tab" {
            MovePane
        }
        bind "p" {
            MovePaneBackwards
        }
        bind "h" "Left" {
            MovePane "Left"
        }
        bind "j" "Down" {
            MovePane "Down"
        }
        bind "k" "Up" {
            MovePane "Up"
        }
        bind "l" "Right" {
            MovePane "Right"
        }
    }
    tab {
        bind "t" {
            SwitchToMode "Normal"
        }
        bind "r" {
            SwitchToMode "RenameTab"
            TabNameInput 0
        }
        bind "h" "Left" "Up" "k" {
            GoToPreviousTab
        }
        bind "l" "Right" "Down" "j" {
            GoToNextTab
        }
        bind "n" {
            NewTab
            SwitchToMode "Locked"
        }
        bind "x" {
            CloseTab
            SwitchToMode "Locked"
        }
        bind "s" {
            ToggleActiveSyncTab
            SwitchToMode "Locked"
        }
        bind "b" {
            BreakPane
            SwitchToMode "Locked"
        }
        bind "]" {
            BreakPaneRight
            SwitchToMode "Locked"
        }
        bind "[" {
            BreakPaneLeft
            SwitchToMode "Locked"
        }
        bind "1" {
            GoToTab 1
            SwitchToMode "Locked"
        }
        bind "2" {
            GoToTab 2
            SwitchToMode "Locked"
        }
        bind "3" {
            GoToTab 3
            SwitchToMode "Locked"
        }
        bind "4" {
            GoToTab 4
            SwitchToMode "Locked"
        }
        bind "5" {
            GoToTab 5
            SwitchToMode "Locked"
        }
        bind "6" {
            GoToTab 6
            SwitchToMode "Locked"
        }
        bind "7" {
            GoToTab 7
            SwitchToMode "Locked"
        }
        bind "8" {
            GoToTab 8
            SwitchToMode "Locked"
        }
        bind "9" {
            GoToTab 9
            SwitchToMode "Locked"
        }
        bind "Tab" {
            ToggleTab
        }
    }
    scroll {
        bind "s" {
            SwitchToMode "Normal"
        }
        bind "e" {
            EditScrollback
            SwitchToMode "Locked"
        }
        bind "f" {
            SwitchToMode "EnterSearch"
            SearchInput 0
        }
        bind "Ctrl c" {
            ScrollToBottom
            SwitchToMode "Locked"
        }
        bind "j" "Down" {
            ScrollDown
        }
        bind "k" "Up" {
            ScrollUp
        }
        bind "Ctrl f" "PageDown" "Right" "l" {
            PageScrollDown
        }
        bind "Ctrl b" "PageUp" "Left" "h" {
            PageScrollUp
        }
        bind "d" {
            HalfPageScrollDown
        }
        bind "u" {
            HalfPageScrollUp
        }
        bind "Alt left" {
            MoveFocusOrTab "left"
            SwitchToMode "locked"
        }
        bind "Alt down" {
            MoveFocus "down"
            SwitchToMode "locked"
        }
        bind "Alt up" {
            MoveFocus "up"
            SwitchToMode "locked"
        }
        bind "Alt right" {
            MoveFocusOrTab "right"
            SwitchToMode "locked"
        }
        bind "Alt h" {
            MoveFocusOrTab "left"
            SwitchToMode "locked"
        }
        bind "Alt j" {
            MoveFocus "down"
            SwitchToMode "locked"
        }
        bind "Alt k" {
            MoveFocus "up"
            SwitchToMode "locked"
        }
        bind "Alt l" {
            MoveFocusOrTab "right"
            SwitchToMode "locked"
        }
    }
    search {
        bind "Ctrl c" {
            ScrollToBottom
            SwitchToMode "Locked"
        }
        bind "j" "Down" {
            ScrollDown
        }
        bind "k" "Up" {
            ScrollUp
        }
        bind "Ctrl f" "PageDown" "Right" "l" {
            PageScrollDown
        }
        bind "Ctrl b" "PageUp" "Left" "h" {
            PageScrollUp
        }
        bind "d" {
            HalfPageScrollDown
        }
        bind "u" {
            HalfPageScrollUp
        }
        bind "n" {
            Search "down"
        }
        bind "p" {
            Search "up"
        }
        bind "c" {
            SearchToggleOption "CaseSensitivity"
        }
        bind "w" {
            SearchToggleOption "Wrap"
        }
        bind "o" {
            SearchToggleOption "WholeWord"
        }
    }
    entersearch {
        bind "Ctrl c" "Esc" {
            SwitchToMode "Scroll"
        }
        bind "Enter" {
            SwitchToMode "Search"
        }
    }
    renametab {
        bind "Ctrl c" "Enter" {
            SwitchToMode "Locked"
        }
        bind "Esc" {
            UndoRenameTab
            SwitchToMode "Tab"
        }
    }
    renamepane {
        bind "Ctrl c" "Enter" {
            SwitchToMode "Locked"
        }
        bind "Esc" {
            UndoRenamePane
            SwitchToMode "Pane"
        }
    }
    session {
        bind "o" {
            SwitchToMode "Normal"
        }
        bind "d" {
            Detach
        }
        bind "w" {
            LaunchOrFocusPlugin "session-manager" {
                floating true
                move_to_focused_tab true
            }
            SwitchToMode "Locked"
        }
        bind "c" {
            LaunchOrFocusPlugin "configuration" {
                floating true
                move_to_focused_tab true
            }
            SwitchToMode "Locked"
        }
        bind "p" {
            LaunchOrFocusPlugin "plugin-manager" {
                floating true
                move_to_focused_tab true
            }
            SwitchToMode "Locked"
        }
        bind "a" {
            LaunchOrFocusPlugin "zellij:about" {
                floating true
                move_to_focused_tab true
            }
            SwitchToMode "Locked"
        }
        bind "s" {
            LaunchOrFocusPlugin "zellij:share" {
                floating true
                move_to_focused_tab true
            }
            SwitchToMode "Locked"
        }
    }
    shared_except "locked" "renametab" "renamepane" {
        bind "ctrl g" {
            SwitchToMode "Locked"
        }
        bind "ctrl q" {
            Quit
        }
    }
    shared_except "renamepane" "renametab" "entersearch" "locked" {
        bind "esc" {
            SwitchToMode "locked"
        }
    }
    shared_among "normal" "locked" {
        bind "Alt n" {
            NewPane
        }
        bind "Alt f" {
            ToggleFloatingPanes
        }
        bind "Alt a" {
            Run "opencode" {
                close_on_exit true
            }
        }
        bind "Alt i" {
            MoveTab "Left"
        }
        bind "Alt o" {
            MoveTab "Right"
        }
        bind "Alt h" "Alt Left" {
            MoveFocusOrTab "Left"
        }
        bind "Alt l" "Alt Right" {
            MoveFocusOrTab "Right"
        }
        bind "Alt j" "Alt Down" {
            MoveFocus "Down"
        }
        bind "Alt k" "Alt Up" {
            MoveFocus "Up"
        }
        bind "Alt Shift h" "Alt Shift Left" {
            MovePane "Left"
        }
        bind "Alt Shift l" "Alt Shift Right" {
            MovePane "Right"
        }

